function match(tag) {
    const parts = String(tag || "").split(/[.@]/)[0].replace(/_/g,"-").toLowerCase().split("-");
    const base = parts[0];
    if (base === "ru") return "uk";
    if (base === "zh") {
        for (const part of parts) { if (part === "hant") return "zh-Hant"; if (part === "hans") return "zh-Hans"; }
        if (parts.some(part => part.length === 4)) return "";
        return parts.some(part => ["tw","hk","mo"].indexOf(part) >= 0) ? "zh-Hant" : "zh-Hans";
    }
    return ["en","es","fr","de","pt","ja","uk","hi","it","ko","id","pl"].indexOf(base) >= 0 ? base : "";
}
function detect(tags) {
    for (const tag of tags) { const code = match(tag); if (code) return code; }
    return "en";
}
function text(code, source, args) {
    const catalog = dictionaries[code] || {};
    let value = typeof catalog[source] === "string" && catalog[source] ? catalog[source] : source;
    // One pass avoids expanding placeholder-like text supplied by providers.
    return value.replace(/%([1-9][0-9]*)/g, function(_, n) { return args && Number(n) <= args.length ? String(args[Number(n)-1]) : "%" + n; });
}
